const input = $json.body ?? {};
if ($json.headers?.['x-sage-drive-token'] !== $env.SAGE_DRIVE_TOOL_TOKEN) throw new Error('Unauthorized Drive tool request');
const action = String(input.action ?? '');
if (!['SEARCH', 'CREATE_FOLDER', 'RENAME', 'DELETE'].includes(action)) throw new Error('Unsupported Drive action');
const fileId = String(input.fileId ?? '');
if (['RENAME', 'DELETE'].includes(action) && !/^[A-Za-z0-9_-]{1,200}$/.test(fileId)) throw new Error('Invalid Drive file ID');
const name = String(input.name ?? '').trim();
if (['CREATE_FOLDER', 'RENAME'].includes(action) && (!name || name.length > 500)) throw new Error('Invalid Drive name');
const parentId = String(input.parentId ?? '');
if (parentId && !/^[A-Za-z0-9_-]{1,200}$/.test(parentId)) throw new Error('Invalid Drive parent ID');
const escapedQuery = String(input.query ?? '').replace(/'/g, "\\'");
const query = escapedQuery ? `name contains '${escapedQuery}' and trashed = false` : 'trashed = false';
const fields = 'files(id,name,mimeType,modifiedTime,createdTime,webViewLink,parents,owners(emailAddress,displayName),size)';
const requestMethod = {SEARCH:'GET', CREATE_FOLDER:'POST', RENAME:'PATCH', DELETE:'DELETE'}[action];
let requestUrl = `https://www.googleapis.com/drive/v3/files?q=${encodeURIComponent(query)}&pageSize=50&orderBy=modifiedTime%20desc&fields=${encodeURIComponent(fields)}`;
let requestBody = {};
if (action === 'CREATE_FOLDER') { requestUrl = 'https://www.googleapis.com/drive/v3/files?fields=id,name,mimeType,modifiedTime,webViewLink,parents'; requestBody = {name, mimeType:'application/vnd.google-apps.folder', ...(parentId ? {parents:[parentId]} : {})}; }
if (action === 'RENAME') { requestUrl = `https://www.googleapis.com/drive/v3/files/${fileId}?fields=id,name,mimeType,modifiedTime,webViewLink,parents`; requestBody = {name}; }
if (action === 'DELETE') requestUrl = `https://www.googleapis.com/drive/v3/files/${fileId}`;
return [{json:{accountKey:'personal-work', action, requestBody, requestMethod, requestUrl, shouldSendBody:['POST','PATCH'].includes(requestMethod)}}];

